for L, books in BOOKS.items():
    txt = re.sub(r'-\n\s*', '', '\n'.join((K / f'{b}.txt').read_text() for b in books))
    flat = re.sub(r'\s+', ' ', txt)
    out += [f'## {L}', '', '| Kavram | Kitaplardaki yazılışlar (adet) | Örnek |', '|---|---|---|']
    for name, pat in C[L]:
        c = collections.Counter(m.group(0) for m in re.finditer(pat, flat))
        top = ', '.join(f'{w} ({n})' for w, n in c.most_common(6)) or '—'
        m = re.search(pat, flat); ex = flat[max(0, m.start() - 60):m.end() + 70].replace('|', '/') if m else ''
        out.append(f'| {name} | {top} | …{ex}… |')
    out.append('')
pathlib.Path('/home/claude/mahinev/docs/dil-terimleri.md').write_text('\n'.join(out))
